// Fork of "tex3d" by tikabom. https://shadertoy.com/view/sd3fDN
// Quick fix of its plain cyan.
// 2023-01-14 18:44:04

vec2 get_2D_atlas_coordinate(in vec3 uvw) {
    float z = uvw.z * 64.0;
    float c = floor(mod(z, 8.0));
    float r = floor(uvw.z * 8.0);
    float normalized_x = (c + uvw.x) / 8.0;
    float normalized_y = (r + uvw.y) / 8.0;
    return vec2(normalized_x, normalized_y);
}

vec4 tex3D(in sampler2D atlas, in vec3 uvw) {
    vec2 sample1 = get_2D_atlas_coordinate(uvw); 
    vec2 sample2 = get_2D_atlas_coordinate(vec3(uvw.xy, min(1.0, uvw.z + (1.0 / 64.0))));

    vec4 color1 = texture(atlas, sample1);
    vec4 color2 = texture(atlas, sample2);

    float z = uvw.z * 64.0;
    float fraction = fract(z);
    vec4 colorz = color1 * (1.0 - fraction)  + color2 * (fraction);

    return colorz;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 uvw = vec3(fragCoord / iResolution.xy, fract(iTime * 0.01));

    fragColor = tex3D(iChannel0, uvw);
}
